window.REPORT_PRELOAD_CACHE["WMT.html"] = {"version":"551ed521b96119c9c20f0ae4c9dc676f3ade1e4633e73e7fd4180c75e5c328ae","html":"html_content = \"\"\"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>沃尔玛 Walmart (NYSE: WMT) 深度研究报告：从全球零售巨头到全渠道数智化供应链与多元化生态引擎</title>\n    <!-- Tailwind CSS -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <!-- Chart.js -->\n    <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n    <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n    <script>\n    tailwind.config = {\n        darkMode: 'class',\n        theme: {\n            extend: {\n                fontFamily: {\n                    sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n                    mono: ['JetBrains Mono', 'monospace'],\n                },\n                colors: {\n                    navy: {\n                        950: '#070B14',\n                        900: '#0F172A',\n                        800: '#1E293B',\n                        700: '#334155',\n                    },\n                    walmart: {\n                        400: '#38BDF8',\n                        500: '#0071CE',\n                        600: '#004C91',\n                        spark: '#FFC220',\n                    },\n                    accent: {\n                        500: '#3B82F6',\n                        600: '#2563EB',\n                    },\n                    teal: {\n                        500: '#06B6D4',\n                        600: '#0891B2',\n                    }\n                }\n            }\n        }\n    }\n    </script>\n\n    <style>\n    ::-webkit-scrollbar {\n        width: 6px;\n        height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n        background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n        background: #94A3B8;\n        border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n        background: #475569;\n    }\n\n    @media print {\n        #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n            display: none !important;\n        }\n        main {\n            margin-left: 0 !important;\n            padding: 0 !important;\n        }\n        section {\n            break-inside: avoid;\n        }\n    }\n\n    .report-card {\n        transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n        transform: translateY(-2px);\n    }\n\n    .nav-link.active {\n        background: linear-gradient(90deg, rgba(0, 113, 206, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n        border-left: 3px solid #0071CE;\n        color: #FFFFFF;\n        font-weight: 600;\n    }\n    </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-walmart-500 selection:text-white transition-colors duration-200\">\n\n    <!-- 顶部全局阅读进度条 -->\n    <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n        <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-walmart-500 via-amber-400 to-teal-500 w-0 transition-all duration-150\"></div>\n    </div>\n\n    <!-- 移动端顶部导航栏 -->\n    <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n        <div class=\"flex items-center space-x-2.5\">\n            <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-walmart-500 to-walmart-600 flex items-center justify-center font-extrabold text-white shadow\">\n                WM\n            </div>\n            <div>\n                <div class=\"text-[11px] text-walmart-400 font-semibold tracking-wider uppercase\">NYSE: WMT · Equity Research</div>\n                <div class=\"text-sm font-bold leading-tight\">沃尔玛 Walmart 深度研究报告</div>\n            </div>\n        </div>\n        <div class=\"flex items-center space-x-2\">\n            <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n                <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n            </button>\n            <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n                <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n            </button>\n        </div>\n    </header>\n\n    <!-- 移动端折叠抽屉菜单 -->\n    <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n        <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n        <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n            <div>\n                <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n                    <span class=\"font-bold text-white text-base\">WMT 研报目录导航</span>\n                    <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n                        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n                    </button>\n                </div>\n                <ul class=\"mt-4 space-y-1.5 text-sm\">\n                    <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n                    <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n                    <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n                    <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n                    <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n                    <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n                    <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n                </ul>\n            </div>\n            <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n                <p>全球零售与全渠道供应链研究组</p>\n                <p class=\"mt-1\">数据基准：2026年11月 (FY2027E)</p>\n            </div>\n        </nav>\n    </div>\n\n    <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n    <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n        <div>\n            <!-- 机构品牌头 -->\n            <div class=\"p-5 border-b border-slate-800/80\">\n                <div class=\"flex items-center space-x-3\">\n                    <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-walmart-500 to-walmart-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-walmart-500/25\">\n                        WMT\n                    </div>\n                    <div>\n                        <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-walmart-400 bg-walmart-500/15 px-2 py-0.5 rounded\">NYSE: WMT</span>\n                        <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">沃尔玛深度研报</h2>\n                    </div>\n                </div>\n                <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n                    全球实体零售绝对霸主 · 数字化全渠道与高利润广告电商引擎\n                </p>\n            </div>\n\n            <!-- 股票实时快照徽章 -->\n            <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">FY2026 全年营收</span>\n                    <span class=\"font-mono font-bold text-white\">~$681.0B <span class=\"text-walmart-400\">(+5.5%)</span></span>\n                </div>\n                <div class=\"flex items-center justify-between\">\n                    <span class=\"text-slate-400\">电商与广告占比</span>\n                    <span class=\"font-mono font-bold text-teal-400\">Walmart Connect 高增长</span>\n                </div>\n                <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n                    <span class=\"text-slate-400\">远期估值锚</span>\n                    <span class=\"font-mono font-bold text-walmart-400\">~28.5x P/E (高质转型溢价)</span>\n                </div>\n            </div>\n\n            <!-- 六个核心章节目录导航 -->\n            <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n                <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n                <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n                    <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-walmart-400 mr-2\">00</span>执行摘要与核心指标</span>\n                    </a>\n                    <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n                    </a>\n                    <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n                    </a>\n                    <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n                    </a>\n                    <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n                    </a>\n                    <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n                    </a>\n                    <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n                        <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n                    </a>\n                </nav>\n            </div>\n        </div>\n\n        <!-- 侧边栏底部工具栏 -->\n        <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n            <div class=\"flex items-center justify-between\">\n                <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n                <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n                    <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n                    <svg class=\"w-3.5 h-3.5 text-walmart-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n                    <span class=\"dark:hidden\">深色护眼模式</span>\n                    <span class=\"hidden dark:inline\">机构亮色模式</span>\n                </button>\n            </div>\n            <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-walmart-500 hover:bg-walmart-600 text-white text-xs font-extrabold transition shadow-sm\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n                <span>打印 / 导出 PDF 研报</span>\n            </button>\n        </div>\n    </aside>\n\n    <!-- 主内容区 -->\n    <main class=\"lg:ml-[280px] min-h-screen\">\n        <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n            <!-- =========================================================\n            00. Hero 研报封面区与执行摘要\n            ========================================================= -->\n            <section id=\"sec-exec\" class=\"scroll-mt-20\">\n                <!-- 顶部研报元数据标签栏 -->\n                <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n                    <div class=\"flex flex-wrap items-center gap-2\">\n                        <span class=\"px-2.5 py-1 rounded-md bg-walmart-500/15 text-walmart-600 dark:text-walmart-400 font-bold border border-walmart-500/30\">评级：强烈买入 / 全球零售核心防御与成长标的</span>\n                        <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：全渠道数智化转型与高利润广告加速期</span>\n                    </div>\n                    <div class=\"flex items-center space-x-3 font-mono\">\n                        <span>覆盖时间：2026年11月</span>\n                        <span>NYSE: WMT</span>\n                    </div>\n                </div>\n\n                <!-- Hero 标题卡片 -->\n                <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n                    <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#0071CE 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n                    <div class=\"relative z-10\">\n                        <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-walmart-500/20 border border-walmart-500/40 text-walmart-400 text-xs font-semibold mb-4\">\n                            <span class=\"w-2 h-2 rounded-full bg-walmart-400 animate-pulse\"></span>\n                            <span>CORE THESIS · 实体规模优势与全渠道履约网 × Walmart Connect 广告与电商高利润生态重估</span>\n                        </div>\n                        <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n                            沃尔玛 Walmart Inc. (NYSE: WMT) 深度研究报告：从全球实体零售霸主到全渠道数智化供应链与多元化生态引擎\n                        </h1>\n                        <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n                            沃尔玛已成功超越传统意义上的“平价超市”，蜕变为集<strong class=\"text-white\">实体零售、全渠道电商、高利润零售媒体广告（Walmart Connect）及金融科技</strong>于一体的全球数智化商业生态巨头。FY2026 全年营收逼近 <strong class=\"text-walmart-400\">$681.0B</strong>，全球电商销售额保持双位数强劲增长。\n                            得益于高利润率的广告与第三方 Marketplace 服务收入占比提升，公司盈利增速持续跑赢营收，推动估值体系向“高质科技零售平台”稳步跃升。\n                        </p>\n\n                        <!-- 核心投资结论高亮条 -->\n                        <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">全渠道电商与履约闭环</div>\n                                <div class=\"text-white font-semibold\">门店即仓（Store-Fulfilled）履约网络驱动全球电商 GMV 持续突破新高</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">高利润广告引擎驱动</div>\n                                <div class=\"text-walmart-400 font-semibold\">Walmart Connect 零售广告业务高速扩张，深刻重塑整体净利润率结构</div>\n                            </div>\n                            <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                                <div class=\"text-slate-400 font-medium mb-1\">宏观防御与消费降级首选</div>\n                                <div class=\"text-teal-400 font-semibold\">高收入客群（High-Income Households）渗透率不断提升，基本盘稳如磐石</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 4个核心 KPI 卡片 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n                    <!-- KPI 1 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>FY2026 全年总营收</span>\n                            <span class=\"p-1.5 rounded-lg bg-walmart-500/15 text-walmart-600 dark:text-walmart-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$681.0B</span>\n                            <span class=\"text-xs font-bold text-walmart-600 dark:text-walmart-400 bg-walmart-500/15 px-2 py-0.5 rounded\">+5.5% YoY</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            在全球最大零售体量下依然保持稳健扩张，实体门店与线上杂货需求保持强劲。\n                        </p>\n                    </div>\n\n                    <!-- KPI 2 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>全球电商渗透率与 GMV</span>\n                            <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;$100B</span>\n                            <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">电商双位数高增</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            全球电商规模突破千亿美元大关，由店配（Delivery from Store）与第三方 Marketplace 强力驱动。\n                        </p>\n                    </div>\n\n                    <!-- KPI 3 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>Walmart Connect 广告业务</span>\n                            <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">&gt;20% YoY</span>\n                            <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">高利润增量</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            零售媒体网络保持高速增长，成为推动公司营业利润增速超越营收增速的核心杠杆。\n                        </p>\n                    </div>\n\n                    <!-- KPI 4 -->\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n                            <span>远期估值锚 (Forward P/E)</span>\n                            <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n                            </span>\n                        </div>\n                        <div class=\"mt-3 flex items-baseline space-x-2\">\n                            <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~28.5x</span>\n                            <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">享有科技零售溢价</span>\n                        </div>\n                        <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n                            市场对其数智化转型与高利润广告/会员服务给予估值重估（Re-rating），估值倍数稳居传统零售业之首。\n                        </p>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            一、 业务与收入架构 (Business & Revenue Architecture)\n            ========================================================= -->\n            <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-walmart-600 dark:text-walmart-400\">Section 01 · Business & Revenue Architecture</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：四大支柱驱动全球最大零售商业矩阵</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026 总营收 ~$681.0B · 美国本土占比 ~78%</span>\n                </div>\n\n                <!-- 交互式 Chart.js 双视图切换面板 -->\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n                    <!-- 左侧：双视图图表 -->\n                    <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n                            <div>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2023–FY2027E 核心板块营收演进（Walmart US vs International vs Sam's Club）</h3>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">美国本土市场与山姆会员店稳健增长，国际业务持续优化</p>\n                            </div>\n                            <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                                <button onclick=\"switchBizChart('revenue')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-walmart-600 dark:text-walmart-400 shadow-sm transition\">视图A：分部营收演进</button>\n                                <button onclick=\"switchBizChart('ecosystem')\" id=\"btn-chart-eco\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：高利生态贡献 (广告/电商)</button>\n                            </div>\n                        </div>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"bizArchitectureChart\"></canvas>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：结构性拆解核心洞察 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性转型</h3>\n                            <ul class=\"space-y-4 text-sm\">\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-walmart-500/15 text-walmart-600 dark:text-walmart-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">Walmart U.S.（美国沃尔玛）基本盘</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            贡献集团近 70% 的总营收。依托庞大的门店网络，杂货（Grocery）与日用消耗品需求极具抗周期性，且高收入家庭客群渗透率持续提升。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">Sam's Club（山姆会员店）高速增长</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            仓储会员制模式展现强大黏性，会员费收入稳步增长，客单价与同店销售额（Comparable Sales）持续跑赢传统零售。\n                                        </p>\n                                    </div>\n                                </li>\n                                <li class=\"flex items-start space-x-3\">\n                                    <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                                    <div>\n                                        <div class=\"font-semibold text-slate-900 dark:text-white\">Walmart Connect 广告与生态变现</div>\n                                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                            零售媒体网络（Retail Media Network）利用海量消费者购物数据为品牌商提供精准营销，毛利率高达 70%–80% 级别，是盈利结构优化的核心。\n                                        </p>\n                                    </div>\n                                </li>\n                            </ul>\n                        </div>\n                        <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n                            <span class=\"text-slate-500 dark:text-slate-400\">核心转型抓手</span>\n                            <span class=\"font-bold text-walmart-600 dark:text-walmart-400\">全渠道履约网 (Store-Fulfilled Delivery)</span>\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 核心业务板块矩阵卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-walmart-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-walmart-500/15 text-walmart-600 dark:text-walmart-400 text-xs font-bold\">基本盘 · 占比 ~69%</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$470B+</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">1. Walmart U.S.</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                美国本土大卖场与 Neighborhood Market。凭借极致的供应链议价能力保障民生刚需，同时门店兼任微型物流履约中心。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n                            杂货电商化 · 店配极速达\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">高增长 · 占比 ~15%</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$90B+</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. Sam's Club</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                美国及国际山姆会员店。会员费收入稳定，高品质自有品牌（Member's Mark）渗透率持续提升，客群黏性极强。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n                            仓储会员制 · 续费率创新高\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">海外版图 · 占比 ~16%</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">~$110B+</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. Walmart International</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                覆盖墨西哥（Walmex）、加拿大及 Flipkart（印度电商巨头）等核心海外资产，贡献重要的战略增长极。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n                            Flipkart 协同 · 拉美与印度布局\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-amber-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-3\">\n                                <span class=\"px-2.5 py-1 rounded-md bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">高利引擎 · 广告与电商</span>\n                                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">高利润率爆发</span>\n                            </div>\n                            <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. Walmart Connect & Marketplace</h3>\n                            <p class=\"mt-2 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                零售媒体广告与第三方商家平台。通过数字化广告变现与物流履约服务（WFS），全方位重塑集团利润结构。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold\">\n                            RMN 高速增长 · 利润增速超营收\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            二、 行业地位与四重核心护城河 (Industry Position & Moat)\n            ========================================================= -->\n            <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：实体网络、供应链与数字化生态</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球线下与线上融合的商业壁垒)</span>\n                </div>\n\n                <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n                    <!-- 左侧：四重护城河深度解析 -->\n                    <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-walmart-500/15 text-walmart-600 dark:text-walmart-400 flex items-center justify-center font-bold text-sm\">01</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">门店即仓（Store-Fulfilled）履约网络</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                美国 90% 的人口居住在距离沃尔玛门店 10 英里以内。数千家实体大卖场无缝转换为高效的微型履约中心，实现极低成本的“线上下单、门店配送/自提”。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">极致的全球供应链议价与物流规模</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                凭借全球庞大的采购体量与自动化物流配送中心，对上游供应商拥有无可比拟的议价权，确保“天天平价（EDLP）”的心智壁垒。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Walmart Connect 零售媒体网络</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                利用线上线下数亿消费者的高频购物行为数据，为品牌商提供闭环广告投放与归因分析，构筑起传统零售商难以复制的高利润软件级护城河。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                                <span class=\"w-8 h-8 rounded-lg bg-amber-500/15 text-amber-600 dark:text-amber-400 flex items-center justify-center font-bold text-sm\">04</span>\n                                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Walmart+ 会员与高收入客群渗透</h3>\n                            </div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                通过 Walmart+ 会员体系绑定免费配送、流媒体合作及加油优惠，成功吸引大量中高收入家庭（High-Income Households）转向沃尔玛采购，大幅拓宽用户盘。\n                            </p>\n                        </div>\n                    </div>\n\n                    <!-- 右侧：五维护城河雷达图 -->\n                    <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">全球零售与电商五维护城河量化雷达图</h3>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">沃尔玛 (WMT) vs 传统纯电商平台 vs 纯线下实体超市（满分 10 分）</p>\n                        <div class=\"relative h-72 w-full\">\n                            <canvas id=\"moatRadarChart\"></canvas>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            三、 同行竞争格局横向对比 (Competitive Landscape)\n            ========================================================= -->\n            <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-walmart-600 dark:text-walmart-400\">Section 03 · Global Competitive Landscape</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：全渠道零售霸主 vs 纯电商与仓储同行</h2>\n                    </div>\n                    <!-- 交互式筛选按钮 -->\n                    <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n                        <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-walmart-500 text-white shadow-sm transition\">全部阵营</button>\n                        <button onclick=\"filterCompetitors('omnichannel')\" data-filter=\"omnichannel\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">全渠道与实体零售巨头</button>\n                        <button onclick=\"filterCompetitors('pureplay')\" data-filter=\"pureplay\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">纯电商与仓储会员制</button>\n                    </div>\n                </div>\n\n                <!-- 横向对比矩阵表格 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n                    <div class=\"overflow-x-auto\">\n                        <table class=\"w-full text-left border-collapse\">\n                            <thead>\n                                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                                    <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心平台</th>\n                                    <th class=\"py-4 px-4 min-w-[130px]\">业务定位与商业模式</th>\n                                    <th class=\"py-4 px-4 min-w-[140px]\">实体网络/履约优势</th>\n                                    <th class=\"py-4 px-4 min-w-[135px]\">毛利率与广告变现</th>\n                                    <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞争评估</th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                                <tr data-category=\"omnichannel\" class=\"bg-walmart-500/5 dark:bg-walmart-500/10 font-medium\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"flex items-center space-x-2\">\n                                            <span class=\"px-2 py-0.5 rounded bg-walmart-500 text-white text-[10px] font-extrabold\">行业霸主</span>\n                                            <span class=\"font-bold text-slate-900 dark:text-white\">沃尔玛 Walmart (WMT)</span>\n                                        </div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球最大全渠道零售与广告巨头</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">实体大卖场 + 全渠道电商 + RMN</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">美国本土 4700+ 门店即仓履约</td>\n                                    <td class=\"py-4 px-4 font-mono font-bold text-walmart-600 dark:text-walmart-400\">毛利 ~24% (广告高增)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>全渠道融合典范：</strong>完美结合线下实体杂货优势与线上店配网，抗宏观周期波动能力最强。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"pureplay\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">亚马逊 Amazon.com (AMZN)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球电商与云计算绝对领头羊</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">纯线上电商 + AWS 云计算 + 广告</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">庞大现代化物流中心网络</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">整体毛利高 (~45%+ 含AWS)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>线上与云端垄断：</strong>在全品类综合电商与企业级云计算（AWS）占据绝对优势，但在生鲜杂货高频线下场景上不及沃尔玛。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"pureplay\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">开市客 Costco (COST)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球仓储会员制零售标杆</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">付费会员制 + 极简SKU大包装</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">高坪效大面积仓储会员店</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">商品毛利极低 (~11-13%)</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>极致会员忠诚度：</strong>依靠会员费实现惊人利润率，但SKU数量精简，在长尾商品丰富度及全渠道配送网覆盖上弱于沃尔玛。\n                                    </td>\n                                </tr>\n\n                                <tr data-category=\"omnichannel\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                                    <td class=\"py-4 px-5\">\n                                        <div class=\"font-bold text-slate-900 dark:text-white\">塔吉特 Target (TGT)</div>\n                                        <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">美国中高端百货与时尚零售</div>\n                                    </td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">时尚百货、家居与精选杂货</td>\n                                    <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">中等规模时尚门店网络</td>\n                                    <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">中等毛利水平</td>\n                                    <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                                        <strong>美学与可选消费：</strong>在时尚家居与自有品牌设计感上备受青睐，但在基础杂货刚需体量和供应链规模上与沃尔玛存在代差。\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n                </div>\n\n                <!-- 配套 Chart.js 横向条形图：毛利率与广告占比对比 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要零售与电商巨头综合毛利率对比</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">沃尔玛通过高利润 Walmart Connect 广告与第三方平台赋能，稳步推升综合盈利结构</p>\n                        </div>\n                        <span class=\"text-xs font-semibold text-walmart-600 dark:text-walmart-400 bg-walmart-500/15 px-2.5 py-1 rounded\">传统零售向高利润生态转型</span>\n                    </div>\n                    <div class=\"relative h-60 w-full\">\n                        <canvas id=\"compMarginChart\"></canvas>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n            ========================================================= -->\n            <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：千亿级现金流与科技零售估值重估</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">远期 P/E ~28.5x · 股息连续数十年稳步增长</span>\n                </div>\n\n                <!-- 1. 财务健康度四大硬核指标卡 -->\n                <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-walmart-600 dark:text-walmart-400 uppercase\">Gross Margin</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~24.2%</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            得益于广告业务（Walmart Connect）与会员服务高毛利拉动，整体毛利率稳步改善。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Income Growth</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">超营收增速</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            营业利润增速持续快于营收增速，经营杠杆效益在自动化仓储与数字化转型中全面释放。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Operating Cash Flow</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">&gt;$30B / 年</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            庞大且稳定的经营现金流，完美支撑供应链自动化资本开支与持续回报股东。\n                        </p>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                        <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Shareholder Return</div>\n                        <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">股息股王</div>\n                        <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n                            作为标准普尔分红贵族，连续数十年实现年度股息稳步增长，叠加股票回购。\n                        </p>\n                    </div>\n                </div>\n\n                <!-- 2. 交互式 Chart.js 财务演进双轴图 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n                        <div>\n                            <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2023–FY2027E 营收与营业利润爆发增长趋势</h3>\n                            <p class=\"text-xs text-slate-500 dark:text-slate-400\">从传统大卖场向科技零售平台跃升：利润增速超越营收，估值倍数稳步重估至 ~28.5x</p>\n                        </div>\n                        <span class=\"text-xs font-mono font-bold text-walmart-600 dark:text-walmart-400 bg-walmart-500/10 px-2.5 py-1 rounded\">当前 Fwd P/E ~28.5x</span>\n                    </div>\n                    <div class=\"relative h-72 w-full\">\n                        <canvas id=\"valEvolutionChart\"></canvas>\n                    </div>\n                </div>\n\n                <!-- 3. 互动式复利推演计算器 -->\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 sm:p-8 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <div class=\"flex flex-col md:flex-row justify-between md:items-center gap-4 mb-6\">\n                        <div>\n                            <h3 class=\"text-lg font-bold text-white\">沃尔玛 (WMT) 投资回报与复利推演器</h3>\n                            <p class=\"text-xs text-slate-400 mt-1\">模拟在不同营收增速与广告生态毛利扩张下的长期持仓市值与复合回报率</p>\n                        </div>\n                        <span class=\"text-xs px-3 py-1 rounded-full bg-slate-800 text-walmart-300 border border-slate-700\">交互式推演模型</span>\n                    </div>\n\n                    <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-8 items-center\">\n                        <div class=\"space-y-5\">\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">初始投资本金 (USD)</span>\n                                    <span id=\"invVal\" class=\"font-bold text-white\">$20,000</span>\n                                </div>\n                                <input id=\"invSlider\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"20000\" class=\"w-full accent-walmart-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">持有年限 (Years)</span>\n                                    <span id=\"yrVal\" class=\"font-bold text-white\">3 年</span>\n                                </div>\n                                <input id=\"yrSlider\" type=\"range\" min=\"1\" max=\"10\" step=\"1\" value=\"3\" class=\"w-full accent-walmart-400 cursor-pointer\">\n                            </div>\n                            <div>\n                                <div class=\"flex justify-between text-sm mb-1\">\n                                    <span class=\"text-slate-300\">预期年化营收/盈利增速</span>\n                                    <span id=\"grVal\" class=\"font-bold text-walmart-400\">8.5%</span>\n                                </div>\n                                <input id=\"grSlider\" type=\"range\" min=\"2\" max=\"20\" step=\"0.5\" value=\"8.5\" class=\"w-full accent-walmart-400 cursor-pointer\">\n                            </div>\n                        </div>\n\n                        <div class=\"lg:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-4\">\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末预计总资产市值</div>\n                                <div id=\"finalBalance\" class=\"text-2xl font-bold text-white mt-2\">$25,480</div>\n                                <div id=\"totalGainPct\" class=\"text-xs text-walmart-400 mt-1\">累计总回报 +27.4%</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">期末对应隐含股价</div>\n                                <div id=\"impliedPrice\" class=\"text-2xl font-bold text-teal-400 mt-2\">$108.50</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">基于科技零售估值重估</div>\n                            </div>\n                            <div class=\"bg-slate-800/90 p-5 rounded-xl border border-slate-700\">\n                                <div class=\"text-xs text-slate-400\">隐含复合年化回报 (CAGR)</div>\n                                <div id=\"cagrVal\" class=\"text-2xl font-bold text-amber-400 mt-2\">8.5%</div>\n                                <div class=\"text-xs text-slate-400 mt-1\">防御与成长兼备的复利标的</div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            五、 投资决策与风险配置框架 (Investment Decision & Risk)\n            ========================================================= -->\n            <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-walmart-600 dark:text-walmart-400\">Section 05 · Investment Decision & Risk Allocation</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与核心风险</h2>\n                    </div>\n                    <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：全球宏观组合中的核心防御底仓与成长兼备标的</span>\n                </div>\n\n                <!-- 1. 三情景估值推演卡片 -->\n                <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-walmart-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-walmart-500/15 text-walmart-600 dark:text-walmart-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-walmart-600 dark:text-walmart-400\">概率：30%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">估值目标：32x – 35x P/E</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>Walmart Connect 广告与 Marketplace 业务爆发式增长，高利润服务占比超预期，自动化供应链全面压降成本，市场给予纯科技零售高估值。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-walmart-600 dark:text-walmart-400\">\n                            潜在上行空间：+35% 至 +50%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">估值目标：26x – 28x P/E</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>营收维持 5%–6% 稳健增长，电商与广告业务按既定斜率扩张，营业利润增速持续小幅超越营收，股息与回购稳定回报。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n                            潜在上行空间：+15% 至 +25%\n                        </div>\n                    </div>\n\n                    <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n                        <div>\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n                            </div>\n                            <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防御估值：22x – 24x P/E</div>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                                <strong>核心假设：</strong>美国宏观经济陷入严重滞胀或消费断崖式下滑，人工与供应链履约成本刚性上升，高估值面临阶段性均值回归。\n                            </p>\n                        </div>\n                        <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n                            潜在下行回撤：-10% 至 -18%\n                        </div>\n                    </div>\n                </div>\n\n                <!-- 2. 四大核心风险评估矩阵 -->\n                <div>\n                    <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构应对策略</h3>\n                    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 美国宏观消费疲软与通胀压力</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">低收入客群可支配预算缩减</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                尽管沃尔玛吸引了大量高收入家庭，其核心基本盘仍对底层消费者的宏观购买力敏感，通胀持续可能逼使其牺牲部分毛利维持低价。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 人工与供应链履约成本刚性</span>\n                                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">仓储物流与末端配送薪酬上涨</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                作为庞大实体与全渠道雇主，仓储及配送员薪酬福利上涨可能对运营费用率（OpEx）形成阶段性向上压力。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 线上电商与广告竞争加剧</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">亚马逊及新兴电商零售媒体挤压</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                在线上流量获取及品牌商广告预算争夺上，Walmart Connect 面临来自亚马逊及各大零售商 RMN 的激烈竞争。\n                            </p>\n                        </div>\n\n                        <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                            <div class=\"flex items-center justify-between mb-2\">\n                                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 估值处于历史高位区间</span>\n                                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n                            </div>\n                            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">估值倍数重估后的波动风险</h4>\n                            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                                随着 Forward P/E 抬升至 ~28.5x 历史较高分位，市场对季度业绩及电商增速的容错率降低，若增速稍有放缓可能引发短期估值回调。\n                            </p>\n                        </div>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n            ========================================================= -->\n            <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n                <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n                    <div>\n                        <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n                        <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n                    </div>\n                    <div class=\"flex items-center space-x-2 no-print\">\n                        <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-walmart-500/15 text-walmart-600 dark:text-walmart-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n                        <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n                    </div>\n                </div>\n\n                <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n                        点击勾选机构财报追踪已验证达标的核心指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n                    </p>\n\n                    <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n                        <!-- KPI 1 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0071CE] focus:ring-walmart-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 美国同店销售额（Comparable Sales）增速是否稳健</span>\n                                    <span class=\"text-[11px] font-mono text-walmart-600 dark:text-walmart-400 font-semibold shrink-0\">实体基本盘</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪沃尔玛美国及山姆会员店每季同店销售额（剔除燃料影响）与客流量（Traffic）变化趋势。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 2 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0071CE] focus:ring-walmart-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 全球电商销售额（eCommerce）能否维持双位数高增</span>\n                                    <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">全渠道成长引擎</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    核查全球电商 GMV 增速及店配（Delivery from Store）与 Marketplace 第三方商家渗透率。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 3 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0071CE] focus:ring-walmart-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. Walmart Connect 广告业务同比增速是否保持 20%+</span>\n                                    <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">高利变现晴雨表</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    监控零售媒体网络广告收入增速，评估其对整体毛利率与营业利润增速的强力拉动效应。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 4 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0071CE] focus:ring-walmart-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 营业利润增速能否持续快于总营收增速</span>\n                                    <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">经营杠杆验证</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    检查每季财报中 Operating Income 同比增速是否超越 Net Sales 增速，验证高利润业务结构转型成功。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 5 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0071CE] focus:ring-walmart-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 供应链自动化与门店履约成本优化进度</span>\n                                    <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">供应链效率红利</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    跟踪自动化配送中心（Automation DCs）投产进度及对单件履约成本的压降幅度。\n                                </p>\n                            </div>\n                        </label>\n\n                        <!-- KPI 6 -->\n                        <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n                            <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#0071CE] focus:ring-walmart-500\">\n                            <div class=\"flex-1\">\n                                <div class=\"flex items-center justify-between gap-2\">\n                                    <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. Walmart+ 会员渗透率与高收入家庭复购率</span>\n                                    <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">会员生态黏性</span>\n                                </div>\n                                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                                    关注会员订阅数增长及高收入客群在沃尔玛全渠道的消费占比与客单价提升。\n                                </p>\n                            </div>\n                        </label>\n                    </div>\n                </div>\n            </section>\n\n            <!-- =========================================================\n            页脚免责声明 (Disclaimer Footer)\n            ========================================================= -->\n            <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n                <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n                    <span>沃尔玛 Walmart Inc. (NYSE: WMT) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n                    <span>数据基准：FY2026 财报及 2026 年 11 月市场一致预期 (FY27E)</span>\n                </div>\n                <p class=\"leading-relaxed\">\n                    <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、财报电话会议纪要及市场公开一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的财务预测、三情景估值模型及推演数据均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n                </p>\n            </footer>\n\n        </div>\n    </main>\n\n    <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n    <script>\n    function toggleTheme() {\n        const html = document.documentElement;\n        html.classList.toggle('dark');\n        updateChartsTheme();\n    }\n\n    function toggleMobileMenu() {\n        const drawer = document.getElementById('mobile-drawer');\n        drawer.classList.toggle('hidden');\n    }\n\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n        const scrollTop = window.scrollY;\n        const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n        const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n        document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n        let currentId = 'sec-exec';\n        sections.forEach(sec => {\n            const top = sec.offsetTop - 160;\n            if (scrollTop >= top) {\n                currentId = sec.getAttribute('id');\n            }\n        });\n\n        navLinks.forEach(link => {\n            link.classList.remove('active');\n            const numSpan = link.querySelector('span span');\n            if (numSpan) {\n                numSpan.classList.remove('text-walmart-400');\n                numSpan.classList.add('text-slate-500');\n            }\n            if (link.dataset.target === currentId) {\n                link.classList.add('active');\n                if (numSpan) {\n                    numSpan.classList.remove('text-slate-500');\n                    numSpan.classList.add('text-walmart-400');\n                }\n            }\n        });\n    });\n\n    function filterCompetitors(category) {\n        document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n            if (btn.dataset.filter === category) {\n                btn.classList.add('bg-walmart-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            } else {\n                btn.classList.remove('bg-walmart-500', 'text-white', 'font-semibold', 'shadow-sm');\n                btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n            }\n        });\n\n        const rows = document.querySelectorAll('#comp-table-body tr');\n        rows.forEach(row => {\n            const rowCat = row.dataset.category;\n            if (category === 'all' || rowCat === category) {\n                row.style.display = '';\n            } else {\n                row.style.display = 'none';\n            }\n        });\n    }\n\n    const KPI_STORAGE_KEY = 'wmt_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n        try {\n            const saved = localStorage.getItem(KPI_STORAGE_KEY);\n            if (saved) {\n                const stateMap = JSON.parse(saved);\n                document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n                    if (typeof stateMap[cb.id] === 'boolean') {\n                        cb.checked = stateMap[cb.id];\n                    }\n                });\n            }\n        } catch (e) {}\n        updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n        const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n        const total = checkboxes.length;\n        let checkedCount = 0;\n        const stateMap = {};\n\n        checkboxes.forEach(cb => {\n            stateMap[cb.id] = cb.checked;\n            if (cb.checked) checkedCount++;\n        });\n\n        const pct = Math.round((checkedCount / total) * 100);\n        document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n        try {\n            localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n        } catch (e) {}\n    }\n\n    function resetKpiChecklist() {\n        document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            cb.checked = false;\n        });\n        updateKpiChecklist();\n    }\n\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'revenue';\n\n    function getChartColors() {\n        const isDark = document.documentElement.classList.contains('dark');\n        return {\n            text: isDark ? '#CBD5E1' : '#475569',\n            grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n            radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n        };\n    }\n\n    function initBizChart() {\n        const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n        const colors = getChartColors();\n\n        const revConfig = {\n            type: 'bar',\n            data: {\n                labels: ['FY23', 'FY24', 'FY25', 'FY26', 'FY27E'],\n                datasets: [\n                    {\n                        label: 'Walmart U.S. ($B)',\n                        data: [420.6, 441.8, 465.0, 485.0, 510.0],\n                        backgroundColor: '#0071CE',\n                        borderRadius: 4,\n                    },\n                    {\n                        label: \"Sam's Club ($B)\",\n                        data: [84.3, 86.2, 90.0, 94.0, 99.0],\n                        backgroundColor: '#FFC220',\n                        borderRadius: 4,\n                    },\n                    {\n                        label: 'Walmart International ($B)',\n                        data: [101.5, 114.6, 117.0, 122.0, 128.0],\n                        backgroundColor: '#3B82F6',\n                        borderRadius: 4,\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        stacked: true,\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        stacked: true,\n                        max: 750,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        const ecoConfig = {\n            type: 'bar',\n            data: {\n                labels: ['FY23', 'FY24', 'FY25', 'FY26', 'FY27E'],\n                datasets: [\n                    {\n                        label: '全球电商 GMV ($B)',\n                        data: [82, 100, 115, 130, 150],\n                        backgroundColor: '#06B6D4',\n                        borderRadius: 6,\n                        barThickness: 26\n                    },\n                    {\n                        label: 'Walmart Connect 广告收入 ($B)',\n                        data: [2.7, 3.4, 4.1, 5.0, 6.2],\n                        backgroundColor: '#FFC220',\n                        borderRadius: 6,\n                        barThickness: 26\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        max: 180,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                    }\n                }\n            }\n        };\n\n        if (bizChartInstance) bizChartInstance.destroy();\n        bizChartInstance = new Chart(ctx, currentBizMode === 'revenue' ? revConfig : ecoConfig);\n    }\n\n    function switchBizChart(mode) {\n        currentBizMode = mode;\n        const btnRev = document.getElementById('btn-chart-rev');\n        const btnEco = document.getElementById('btn-chart-eco');\n        const titleEl = document.getElementById('biz-chart-title');\n        const subEl = document.getElementById('biz-chart-sub');\n\n        if (mode === 'revenue') {\n            btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-walmart-600 dark:text-walmart-400 shadow-sm transition';\n            btnEco.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = 'FY2023–FY2027E 核心板块营收演进（Walmart US vs International vs Sam\\'s Club）';\n            subEl.textContent = '美国本土市场与山姆会员店稳健增长，国际业务持续优化';\n        } else {\n            btnEco.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-walmart-600 dark:text-walmart-400 shadow-sm transition';\n            btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n            titleEl.textContent = 'FY2023–FY2027E 全球电商 GMV 与 Walmart Connect 广告爆发趋势';\n            subEl.textContent = '高利润广告与电商生态成为推动净利润增速超越营收的核心引擎';\n        }\n        initBizChart();\n    }\n\n    function initRadarChart() {\n        const ctx = document.getElementById('moatRadarChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (radarChartInstance) radarChartInstance.destroy();\n        radarChartInstance = new Chart(ctx, {\n            type: 'radar',\n            data: {\n                labels: [\n                    '实体门店密度与履约网 (Store-Fulfilled)',\n                    '全球供应链议价与每日平价 (EDLP)',\n                    'Walmart Connect 高利润广告变现',\n                    'Sam\\'s Club 仓储会员制忠诚度',\n                    '全渠道数字化与高收入客群渗透'\n                ],\n                datasets: [\n                    {\n                        label: '沃尔玛 Walmart (WMT)',\n                        data: [9.8, 9.8, 9.0, 9.2, 9.4],\n                        borderColor: '#0071CE',\n                        backgroundColor: 'rgba(0, 113, 206, 0.22)',\n                        pointBackgroundColor: '#0071CE',\n                        borderWidth: 2.5\n                    },\n                    {\n                        label: '纯线上电商巨头 (Amazon)',\n                        data: [8.5, 8.0, 9.5, 6.0, 9.6],\n                        borderColor: '#3B82F6',\n                        backgroundColor: 'rgba(59, 130, 246, 0.14)',\n                        pointBackgroundColor: '#3B82F6',\n                        borderWidth: 1.8\n                    },\n                    {\n                        label: '传统实体超市同行',\n                        data: [8.0, 7.5, 4.0, 8.5, 6.0],\n                        borderColor: '#94A3B8',\n                        backgroundColor: 'rgba(148, 163, 184, 0.12)',\n                        pointBackgroundColor: '#94A3B8',\n                        borderWidth: 1.5,\n                        borderDash: [4, 4]\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n                    }\n                },\n                scales: {\n                    r: {\n                        min: 0,\n                        max: 10,\n                        ticks: { display: false, stepSize: 2 },\n                        grid: { color: colors.grid },\n                        angleLines: { color: colors.radarAngle },\n                        pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initCompMarginChart() {\n        const ctx = document.getElementById('compMarginChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (compMarginChartInstance) compMarginChartInstance.destroy();\n        compMarginChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: [\n                    'Amazon (AMZN · 含AWS生态)',\n                    'Costco (COST · 会员制低毛利)',\n                    'Walmart (WMT · 全渠道+广告转型)',\n                    'Target (TGT · 百货时尚零售)'\n                ],\n                datasets: [{\n                    label: '综合毛利率 Gross Margin (%)',\n                    data: [45.5, 12.5, 24.2, 27.5],\n                    backgroundColor: [\n                        '#3B82F6',\n                        '#06B6D4',\n                        '#0071CE',\n                        '#F59E0B'\n                    ],\n                    borderRadius: 6,\n                    barThickness: 24\n                }]\n            },\n            options: {\n                indexAxis: 'y',\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { display: false },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => `综合毛利率: ${ctx.parsed.x}%`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        max: 60,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n                    },\n                    y: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    }\n                }\n            }\n        });\n    }\n\n    function initValEvolutionChart() {\n        const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n        const colors = getChartColors();\n\n        if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n        valEvolutionChartInstance = new Chart(ctx, {\n            type: 'bar',\n            data: {\n                labels: ['FY23', 'FY24', 'FY25', 'FY26', 'FY27E'],\n                datasets: [\n                    {\n                        type: 'bar',\n                        label: '全年总营收 ($B)',\n                        data: [611.3, 648.1, 664.0, 681.0, 715.0],\n                        backgroundColor: 'rgba(0, 113, 206, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 24,\n                        yAxisID: 'y'\n                    },\n                    {\n                        type: 'bar',\n                        label: '营业利润 Operating Income ($B)',\n                        data: [20.4, 27.0, 27.0, 28.5, 31.0],\n                        backgroundColor: 'rgba(255, 194, 32, 0.85)',\n                        borderRadius: 5,\n                        barThickness: 24,\n                        yAxisID: 'y1'\n                    }\n                ]\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: {\n                        position: 'bottom',\n                        labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n                    },\n                    tooltip: {\n                        callbacks: {\n                            label: (ctx) => ctx.dataset.yAxisID === 'y'\n                                ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                                : `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                        }\n                    }\n                },\n                scales: {\n                    x: {\n                        grid: { display: false },\n                        ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n                    },\n                    y: {\n                        type: 'linear',\n                        position: 'left',\n                        max: 850,\n                        grid: { color: colors.grid },\n                        ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n                    },\n                    y1: {\n                        type: 'linear',\n                        position: 'right',\n                        min: 0,\n                        max: 50,\n                        grid: { drawOnChartArea: false },\n                        ticks: { color: '#D97706', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'B' }\n                    }\n                }\n            }\n        });\n    }\n\n    function updateChartsTheme() {\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n    }\n\n    // Calculator Logic\n    const invSlider = document.getElementById('invSlider');\n    const yrSlider = document.getElementById('yrSlider');\n    const grSlider = document.getElementById('grSlider');\n\n    function updateCalculator() {\n        const principal = parseFloat(invSlider.value);\n        const years = parseInt(yrSlider.value);\n        const growthRate = parseFloat(grSlider.value) / 100;\n\n        document.getElementById('invVal').textContent = '$' + principal.toLocaleString();\n        document.getElementById('yrVal').textContent = years + ' 年';\n        document.getElementById('grVal').textContent = (growthRate * 100).toFixed(1) + '%';\n\n        const finalVal = principal * Math.pow(1 + growthRate, years);\n        const totalGain = finalVal - principal;\n        const gainPct = (totalGain / principal) * 100;\n        const impliedPrice = 85 * Math.pow(1 + growthRate * 0.9, years);\n\n        document.getElementById('finalBalance').textContent = '$' + Math.round(finalVal).toLocaleString();\n        document.getElementById('totalGainPct').textContent = '累计总回报 +' + gainPct.toFixed(1) + '%';\n        document.getElementById('impliedPrice').textContent = '$' + impliedPrice.toFixed(2);\n        document.getElementById('cagrVal').textContent = (growthRate * 100).toFixed(1) + '%';\n    }\n\n    [invSlider, yrSlider, grSlider].forEach(el => el.addEventListener('input', updateCalculator));\n\n    window.addEventListener('DOMContentLoaded', () => {\n        loadKpiChecklist();\n        initBizChart();\n        initRadarChart();\n        initCompMarginChart();\n        initValEvolutionChart();\n        updateCalculator();\n    });\n    </script>\n</body>\n</html>\n\"\"\"\n\nwith open(\"walmart_research_dashboard.html\", \"w\", encoding=\"utf-8\") as f:\n    f.write(html_content)\n\nprint(\"Generated walmart_research_dashboard.html successfully.\")"};
